  // 3.0: Simple help and the install-statistics question
  'simple.help.g1.title': 'Einen Bildschirm verbinden',
  'simple.help.g1.s1': 'Öffnen Sie auf dem Fernseher, Tablet oder Computer, den Sie verwenden möchten, den Player: Installieren Sie die Android-App oder öffnen Sie die Seite /player dieser Website im Browser.',
  'simple.help.g1.s2': 'Kein Fernseher zur Hand? Öffnen Sie den Player zum Ausprobieren in einem anderen Browser-Tab.',
  'simple.help.g1.s3': 'Der Player zeigt einen 6-stelligen Code. Wählen Sie hier „Bildschirm hinzufügen“ und geben Sie ihn ein.',
  'simple.help.g1.s4': 'Geben Sie dem Bildschirm einen Namen, den Sie wiedererkennen, z. B. „Schaufenster“.',
  'simple.help.g2.title': 'Ändern, was ein Bildschirm zeigt',
  'simple.help.g2.s1': 'Wählen Sie „Ändern, was ein Bildschirm zeigt“ oder tippen Sie unter „Ihre Bildschirme“ auf den Bildschirm.',
  'simple.help.g2.s2': 'Wählen Sie „Ersetzen“, um nur das Neue zu zeigen, oder „Hinzufügen“, um das Bisherige weiterlaufen zu lassen.',
  'simple.help.g2.s3': 'Laden Sie Fotos oder Videos hoch, wählen Sie bereits hochgeladene aus oder zeigen Sie dasselbe wie auf einem anderen Bildschirm.',
  'simple.help.g2.s4': 'Der Bildschirm aktualisiert sich innerhalb weniger Sekunden.',
  'simple.help.g3.title': 'Fotos und Videos hochladen',
  'simple.help.g3.s1': 'Wählen Sie „Fotos hochladen“ und dann beliebig viele Dateien aus, oder ziehen Sie sie hinein.',
  'simple.help.g3.s2': 'Haken Sie die Bildschirme an, die sie zeigen sollen, oder entfernen Sie alle Haken, um sie für später aufzubewahren.',
  'simple.help.g3.s3': 'Fotos werden je 10 Sekunden gezeigt, Videos laufen bis zum Ende.',
  'simple.help.q1': 'Was kann ich als Bildschirm verwenden?',
  'simple.help.a1': 'Android-Fernseher, TV-Boxen und Tablets, Fire TV, Smart-TVs von LG und Samsung, Raspberry Pi, Windows und ChromeOS – oder jedes Gerät mit Webbrowser.',
  'simple.help.q2': 'Mein Bildschirm ändert sich nicht. Was sollte ich prüfen?',
  'simple.help.a2': 'Prüfen Sie, ob der Bildschirm auf der Startseite „Läuft“ zeigt. Steht dort „Offline“, prüfen Sie, ob das Gerät eingeschaltet und mit dem Internet verbunden ist; Ihre Änderungen kommen an, sobald es wieder verbunden ist.',
  'simple.help.q3': 'Was passiert, wenn das Internet ausfällt?',
  'simple.help.a3': 'Bildschirme speichern die Inhalte lokal und spielen sie weiter ab. Neue Änderungen kommen an, sobald die Verbindung wieder steht.',
  'simple.help.q4': 'Welche Dateien kann ich hochladen?',
  'simple.help.a4': 'Fotos (JPEG, PNG, GIF, WebP) und Videos (MP4 funktioniert am besten) sowie Audio. PDFs können in der Ansicht „Erweitert“ auf der Inhaltsseite hochgeladen werden.',
  'simple.help.q5': 'Wie benenne ich einen Bildschirm um oder entferne ihn?',
  'simple.help.a5': 'Wechseln Sie oben rechts zu „Erweitert“, öffnen Sie „Bildschirme“, klicken Sie auf den Bildschirm und verwenden Sie oben auf seiner Seite „Umbenennen“ oder „Entfernen“.',
  'simple.help.q6': 'Kann ich zu verschiedenen Tageszeiten verschiedene Inhalte zeigen?',
  'simple.help.a6': 'Ja – das ist „Zeitplan“ in der Ansicht „Erweitert“. Die einfache Ansicht zeigt auf einem Bildschirm immer denselben Inhalt, bis Sie ihn ändern.',
  'simple.help.trial_q': 'Wie funktioniert die kostenlose Testphase?',
  'simple.help.trial_a': 'Sie erhalten 14 Tage den Pro-Plan mit allen Funktionen, ohne Kreditkarte. Danach wechseln Sie zum Free-Plan: Nichts wird gelöscht, und Bildschirme über dem Limit des Free-Plans pausieren, bis Sie einen Plan wählen.',
  'stats.prompt.title': 'Helfen Sie zu zeigen, wie verbreitet ScreenTinker ist?',
  'stats.prompt.body': 'Da die meisten Installationen privat sind, wissen wir nicht, wie viele Bildschirme es gibt. Beim Teilen werden eine zufällige ID, die Version und die Anzahl Ihrer Bildschirme gesendet – sonst nichts, niemals. Sie können das jederzeit in den Einstellungen ändern.',
  'stats.prompt.share': 'Teilen',
  'stats.prompt.no': 'Nein, danke',
  'stats.prompt.thanks': 'Danke – Installationsstatistik wird geteilt',
