  'passkey.admin_insecure': 'Passkeys benötigen HTTPS. APP_URL verwendet einfaches http, was Browser nur für localhost erlauben. Stellen Sie diesen Server über HTTPS bereit und setzen Sie APP_URL auf die https://-Adresse.',
  'passkey.admin_ip': 'Passkeys können nicht an eine IP-Adresse gebunden werden. Geben Sie diesem Server einen Hostnamen (auch ein lokaler genügt) und setzen Sie APP_URL darauf.',
