  'exp.mode.location_hint': 'Jede Filiale zeigt während des gesamten Tests eine Version. Am besten, wenn Verkäufe pro Filiale gezählt werden.',
  'exp.mode.time': 'Nach Tageszeit',
  'exp.mode.time_hint': 'Die Versionen wechseln sich auf denselben Bildschirmen ab, alle paar Stunden und je nach Wochentag rotierend. Am besten für einen einzelnen Standort.',
