  'exp.how_title': 'So wird das Ergebnis berechnet',
  'exp.how_1': 'Was jeder Bildschirm tatsächlich gezeigt hat, stammt aus dem Wiedergabenachweis – ein ausgeschalteter Bildschirm zählt also nicht als Anzeige. Eine Stunde zählt nur dann für eine Version, wenn ausschließlich diese Version auf dem Bildschirm war.',
  'exp.how_2': 'Nach Standort wird jede Filiale mit ihren eigenen üblichen Verkäufen vor dem Test verglichen, damit eine große Filiale nicht allein wegen ihrer Größe gewinnt. Nach Tageszeit wechseln sich die Versionen ab und rotieren über die Woche, sodass keine Version alle Stoßzeiten bekommt.',
  'exp.how_3': 'Der angezeigte Bereich (das 95-%-Intervall) entsteht, indem ganze Tage oder ganze Filialen 2.000-mal neu gezogen werden. Schließt er die Null nicht ein, ist der Unterschied wahrscheinlich echt. „Braucht noch etwa N Tage“ schätzt, wie lange es dauert, bis der Bereich eng genug für eine Aussage ist.',
  'exp.privacy': 'Datenschutz: Aus Ihrem Kassensystem werden nur Summen pro Stunde, Filiale und Artikel importiert. Kunden-, Bestell-, Karten- oder Belegdaten werden nie gelesen oder gespeichert.',
  'exp.edit_title': 'Experiment bearbeiten',
