  'exp.approvals_on': 'In diesem Arbeitsbereich werden Änderungen geprüft, bevor sie auf Bildschirme gelangen, daher kann ein Experiment Inhalte nicht selbst wechseln. Schalten Sie die Freigaben in den Einstellungen aus, um Experimente durchzuführen.',
