  'nav.site_caches': 'Standort-Caches',
  'sitecache.intro': 'Ein kleiner, ständig laufender Computer an einem Standort lädt Ihre Medien einmal herunter, und die Bildschirme dort holen sie über das lokale Netzwerk statt über das Internet.',
  'sitecache.how': 'Bildschirme prüfen jede Datei anhand ihres Fingerabdrucks und greifen auf diesen Server zurück, wenn der Cache langsam, ausgefallen oder fehlerhaft ist. Ein Cache kann also Bandbreite sparen, aber nie einen Bildschirm schwarz lassen. Web-Player nutzen ihn ab ihrem nächsten Neustart, Android-Player ab ihrer nächsten Playlist-Aktualisierung. Siehe docs/site-cache.md.',
  'sitecache.new': 'Standort-Cache hinzufügen',
  'sitecache.empty': 'Noch keine Standort-Caches. Fügen Sie einen für Standorte mit vielen Bildschirmen oder langsamem bzw. volumenbegrenztem Internet hinzu.',
