  'sitecache.mixed_content': 'Dieser Server verwendet https, daher können Web-Player den Cache ebenfalls nur über https nutzen (Android-Player können http verwenden). Siehe „HTTPS on the cache“ in der Dokumentation.',
  'sitecache.confirm_rotate': 'Neues Token für „{name}“ erstellen? Der Cache funktioniert erst wieder, wenn Sie ihm das neue Token geben.',
