  'migrate.title': 'Zu ScreenTinker wechseln',
  'migrate.subtitle': 'Übernehmen Sie Ihre Medien, Playlists, Layouts, Zeitpläne und Bildschirme aus einem anderen Signage-System.',
  'migrate.read_only': 'Sie haben für diesen Arbeitsbereich nur Leserechte und können daher nichts importieren.',
  'migrate.q_pick': 'Von welchem System kommen Sie?',
  'migrate.pick_help': 'Wählen Sie Ihr aktuelles System. Wenn es nicht aufgeführt ist, wählen Sie „Ordner mit Medien (zip)“.',
  'migrate.mode.api': 'Mit API-Schlüssel verbinden',
  'migrate.mode.file': 'Datei hochladen',
  'migrate.mode.none': 'Über die API nicht möglich',
  'migrate.recent': 'Letzte Importe',
  'migrate.docs': 'Offizielle Dokumentation:',
  'migrate.optional': '(optional)',
  'migrate.back': 'Zurück',
  'migrate.use_zip': 'Stattdessen den Zip-Import verwenden',
  'migrate.q_connect': 'Mit {vendor} verbinden',
  'migrate.file': 'Exportdatei (.zip)',
  'migrate.choose_file': 'Wählen Sie zuerst eine Datei.',
  'migrate.uploading': 'Wird hochgeladen...',
  'migrate.scan': 'Vorhandenes ansehen',
  'migrate.self_hosted_note': 'Ihr Server muss von diesem ScreenTinker-Server aus erreichbar sein. Adressen in einem privaten Netzwerk sind gesperrt, bis ein Administrator sie freigibt.',
  'migrate.key_note': 'Der Schlüssel wird nur für diesen Import verwendet. Er wird höchstens einige Stunden verschlüsselt aufbewahrt und gelöscht, sobald der Import endet. Lesezugriff genügt.',
  'migrate.timezone_help': 'Wird für Zeitplanzeiten verwendet, wenn die Quelle nicht angibt, in welcher Zeitzone sich ein Bildschirm befindet.',
  'migrate.field.url': 'Serveradresse',
  'migrate.field.client_id': 'Client-ID',
  'migrate.field.client_secret': 'Client-Secret',
  'migrate.field.api_key': 'API-Token (label:token)',
  'migrate.field.token': 'API-Token',
  'migrate.field.username': 'Benutzername',
  'migrate.field.password': 'Passwort',
  'migrate.field.timezone': 'Zeitzone',
  'migrate.field.region': 'Region',
  'migrate.how.xibo': 'Öffnen Sie in Xibo „Administration“, dann „Applications“, und fügen Sie eine Application mit aktivierter Option „Client Credentials“ hinzu. Kopieren Sie deren Client-ID und Client-Secret. Geben Sie Ihre CMS-Adresse ein (die, unter der Sie sich anmelden), zum Beispiel https://cms.example.com.',
  'migrate.how.yodeck': 'Öffnen Sie in Yodeck „Account Settings“, „Advanced Settings“, „API Tokens“ und erzeugen Sie ein Token (Premium- oder Enterprise-Plan). Fügen Sie es als label:token ein. Yodeck gibt ursprünglich hochgeladene Bilder und Dokumente nicht über seine API heraus: Diese werden aufgelistet, damit Sie sie mit dem Zip-Import hinzufügen können. Videos werden in der Version übernommen, die Yodeck abspielt.',
  'migrate.how.optisigns': 'OptiSigns hat eine API, dokumentiert aber keinen Weg, Ihre Dateien herunterzuladen – eine Playlist käme also leer an. Laden Sie Ihre Dateien aus OptiSigns herunter und verwenden Sie den Zip-Import: ein Ordner pro Playlist oder eine playlists.csv.',
  'migrate.how.screencloud': 'Öffnen Sie in ScreenCloud Studio „Account Settings“, dann den Tab „Developer“, und erstellen Sie ein Token mit Leserechten. Wählen Sie die dort angezeigte Region (EU oder US). ScreenCloud speichert Zeitregeln an einzelnen Kanalelementen; diese werden aufgelistet, nicht importiert.',
  'migrate.how.anthias': 'Geben Sie die Adresse Ihres Anthias-Geräts ein, zum Beispiel http://192.168.1.20. Wenn Sie die Authentifizierung aktiviert haben, geben Sie Benutzername und Passwort ein. Jedes Gerät wird als ein Bildschirm mit einer Playlist importiert.',
  'migrate.how.screenly': 'Öffnen Sie in Screenly „Settings“, „Security“, „Tokens“ und fügen Sie ein Token hinzu. Playlists, Labels und Bildschirme werden übernommen; einfache Tages- und Zeitregeln werden zu Zeitplänen.',
  'migrate.how.generic_zip': 'Laden Sie eine Zip-Datei mit Ihren Medien hoch. Jeder Ordner wird zu einer Playlist. Optional können Sie playlists.csv (Spalten: playlist, file, duration, order) und screens.csv (Spalten: name, group, playlist) hinzufügen.',
  'migrate.scanning': 'Vorhandenes wird gelesen. Große Konten brauchen einige Minuten.',
  'migrate.cancel': 'Abbrechen',
  'migrate.found': 'Das wurde gefunden. Wählen Sie, was übernommen werden soll.',
